export function toHealthSegmentRatio(
  value: number,
  scaleMax: number,
  innerHeight: number,
): number {
  const safe = toFiniteNonNegative(value);
  if (safe === 0) {
    return toHealthPxRatio(HEALTH_STACK_ZERO_LINE_PX, innerHeight);
  }
  const max = toFiniteNonNegative(scaleMax);
  if (max === 0) {
    return toHealthPxRatio(HEALTH_STACK_ZERO_LINE_PX, innerHeight);
  }
  return Math.min(safe / max, 1);
}

export function resolveHealthPlotInnerHeight(plotHeight: number, marginY: number): number {
  const inner = plotHeight - marginY;
  if (!Number.isFinite(inner) || inner <= 0) {
    return HEALTH_STACK_FALLBACK_INNER_HEIGHT;
  }
  return inner;
}

export function formatHealthMetricValue(unit: HealthStackUnit, value: number): string {
  const safe = toFiniteNonNegative(value);
  if (unit === 'volume') {
    return formatBRL(safe);
  }
  if (unit === 'percent') {
    return `${safe.toFixed(0)}%`;
  }
  return String(Math.round(safe));
}

export function isProfileHealthEmpty(
  values: ProfileHealthValues,
  teamAvg: ProfileHealthValues,
): boolean {
  return HEALTH_STACK_METRICS.every((metric) => {
    return (
      toFiniteNonNegative(values[metric.key]) === 0 &&
      toFiniteNonNegative(teamAvg[metric.key]) === 0
    );
  });
}

export function buildProfileHealthChartData(
  values: ProfileHealthValues,
  teamAvg: ProfileHealthValues,
  innerHeight = HEALTH_STACK_FALLBACK_INNER_HEIGHT,
): ProfileHealthChartRow[] {
  const gapRatio = toHealthPxRatio(HEALTH_STACK_GAP_PX, innerHeight);

  return HEALTH_STACK_METRICS.map((metric) => {
    const brokerValue = toFiniteNonNegative(values[metric.key]);
    const teamAvgValue = toFiniteNonNegative(teamAvg[metric.key]);
    const reference = HEALTH_STACK_SCALE_MAX[metric.key];

    return {
      name: metric.short,
      metricKey: metric.key,
      teamAvgValue,
      brokerValue,
      reference,
      [HEALTH_STACK_TEAM_KEY]: toHealthSegmentRatio(teamAvgValue, reference, innerHeight),
      [HEALTH_STACK_GAP_KEY]: gapRatio,
      [HEALTH_STACK_BROKER_KEY]: toHealthSegmentRatio(brokerValue, reference, innerHeight),
    };
  });
}

